export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  let scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0.38, 0.38, 0.38);
  scene.useRightHandedSystem = true;

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(-12, -1.5, -5));
  camera.alpha = 2;
  camera.lowerAlphaLimit = 2;
  camera.upperAlphaLimit = 2;
  camera.beta = 1.28;
  camera.lowerBetaLimit = 1.28;
  camera.upperBetaLimit = 1.28;
  camera.radius = 70;
  camera.lowerRadiusLimit = 53;
  camera.upperRadiusLimit = 87;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);

  scene.enablePhysics(new BABYLON.Vector3(0, -30, 0), new BABYLON.AmmoJSPlugin());

  const ground = BABYLON.MeshBuilder.CreateGround("ground", { width: 600, height: 800 }, scene);
  ground.position.y = -1;
  ground.physicsImpostor = new BABYLON.PhysicsImpostor(ground, BABYLON.PhysicsImpostor.BoxImpostor, { mass: 0 }, scene);

  var groundMaterial = new BABYLON.GridMaterial("groundMaterial", scene);
  groundMaterial.majorUnitFrequency = 5;
  groundMaterial.minorUnitVisibility = 0.5;
  groundMaterial.lineColor = BABYLON.Color3.White();
  groundMaterial.gridRatio = 2;
  groundMaterial.opacity = 0.99;
  groundMaterial.useMaxLine = true;
  ground.material = groundMaterial;

  const gap = 0.1;
  const yStartingPos = 10;

  let projectile;
  let clonedProjectile;
  let isObstaclesReady = false;
  let isShoot = false;
  let isShootable = false;

  function HSVtoRGB(h, s, v) {
    let c = v * s;
    let x = c * (1 - Math.abs(((h / 60) % 2) - 1));
    let m = v - c;
    let r, g, b;

    if (h < 60) {
      r = c;
      g = x;
      b = 0;
    } else if (h < 120) {
      r = x;
      g = c;
      b = 0;
    } else if (h < 180) {
      r = 0;
      g = c;
      b = x;
    } else if (h < 240) {
      r = 0;
      g = x;
      b = c;
    } else if (h < 300) {
      r = x;
      g = 0;
      b = c;
    } else {
      r = c;
      g = 0;
      b = x;
    }

    return new BABYLON.Color3(r + m, g + m, b + m);
  }

  function setObstacles() {
    //Pyramid
    for (let i = 0; i < 14; i++) {
      // 1st f: 9  2nd f: 4 3rd f: 1
      const box = BABYLON.MeshBuilder.CreateBox(`box${i}`, { size: 2 }, scene);

      let hue = i * (360 / 14);
      let color = HSVtoRGB(hue, 1, 1);

      let boxMaterial = new BABYLON.StandardMaterial(`mat${i}`, scene);
      boxMaterial.diffuseColor = color;
      box.material = boxMaterial;

      let x, z;

      if (i < 9) {
        x = (i % 3) * (2 + gap) - 2 - gap / 2;
        z = 2 - Math.floor(i / 3) * (2 + gap) + gap / 2;
        box.position.set(x, yStartingPos, z);
      } else if (i >= 9 && i < 13) {
        x = (i % 2) * (2 + gap) - 1 - gap / 2;
        z = i < 11 ? -1 - gap / 2 : 1 + gap / 2;
        box.position.set(x, yStartingPos + 5, z);
      } else {
        box.position.set(0, yStartingPos + 10, 0);
      }

      setTimeout(() => {
        box.physicsImpostor = new BABYLON.PhysicsImpostor(box, BABYLON.PhysicsImpostor.BoxImpostor, { mass: 2, restitution: 0, friction: 4 }, scene);

        if (i === 13) {
          setTimeout(() => {
            isObstaclesReady = true;
            clonedProjectile.setEnabled(true);

            let startPos = clonedProjectile.position.clone().x;
            let targetPos = -35;

            const frameRate = 10;
            const xSlide = new BABYLON.Animation(
              "xSlide",
              "position.x",
              frameRate,
              BABYLON.Animation.ANIMATIONTYPE_FLOAT,
              BABYLON.Animation.ANIMATIONLOOPMODE_CYCLE
            );

            const keyFrames = [];

            keyFrames.push({
              frame: 0,
              value: startPos,
            });

            keyFrames.push({
              frame: 2 * frameRate,
              value: targetPos,
            });

            xSlide.setKeys(keyFrames);

            scene.beginDirectAnimation(clonedProjectile, [xSlide], 0, 2 * frameRate, true);
          }, 1000);
        }
      }, i * 75);
    }
  }

  function setProjectile() {
    const slingshotBase = BABYLON.MeshBuilder.CreateBox("slingshot", { width: 0.3, height: 2, depth: 0.3 }, scene);
    slingshotBase.position.set(-20, 0, 0);
    slingshotBase.setEnabled(false);

    projectile = BABYLON.MeshBuilder.CreateSphere("projectile", { diameter: 2.5 }, scene);
    projectile.material = new BABYLON.PBRMaterial("projMat", scene);
    projectile.material.metallic = 1;
    projectile.material.roughness = 0.771;
    projectile.position.set(-20, 1, 0);

    clonedProjectile = projectile.clone("Clone_Projectile");
    clonedProjectile.isPickable = false;
    clonedProjectile.visibility = 0.3;
    // clonedProjectile.position.y = 3;
    clonedProjectile.setEnabled(false);

    projectile.physicsImpostor = new BABYLON.PhysicsImpostor(
      projectile,
      BABYLON.PhysicsImpostor.SphereImpostor,
      { mass: 7, restitution: 2, friction: 0.5 },
      scene
    );

    let isDragging = false;
    let startPoint = new BABYLON.Vector3();
    let releasePoint = new BABYLON.Vector3();
    let force = new BABYLON.Vector3();
    const fixedY = projectile.position.y;
    const fixedZ = projectile.position.z;

    scene.onPointerDown = (evt, pickInfo) => {
      if (!isObstaclesReady) return;

      if (pickInfo.hit && pickInfo.pickedMesh === projectile) {
        isDragging = true;
        startPoint.copyFrom(pickInfo.pickedPoint);
        console.log("hit");
        clonedProjectile.setEnabled(false);
        camera.detachControl();
      }
    };

    scene.onPointerMove = (evt) => {
      if (isDragging) {
        const pickInfo = scene.pick(scene.pointerX, scene.pointerY);
        if (pickInfo.hit) {
          console.log("move");
          let dragPoint = pickInfo.pickedPoint;

          projectile.position.set(dragPoint.x, fixedY, fixedZ);
        }
      }
    };

    scene.onPointerUp = () => {
      if (!isShootable && !isShoot) {
        isDragging = false;
        projectile.position.set(-20, 1, 0);
        clonedProjectile.setEnabled(true);

        return;
      }

      if (isDragging) {
        const pickInfo = scene.pick(scene.pointerX, scene.pointerY);
        if (pickInfo.hit) {
          releasePoint.copyFrom(pickInfo.pickedPoint);

          force = startPoint.subtract(releasePoint).scale(10);

          force = new BABYLON.Vector3(force.x, 12, 0);

          projectile.physicsImpostor.setLinearVelocity(force);
        }

        function setParticle(targetMesh) {
          var particleSystem = new BABYLON.ParticleSystem("particles", 2000, scene);
          let color1 = BABYLON.Color3.FromInts(249, 115, 0);
          let color2 = BABYLON.Color3.FromInts(222, 93, 54);
          let texture = "https://raw.githubusercontent.com/oriongunning/t5c/main/public/textures/particle_01.png";
          let textureParticule = new BABYLON.Texture(texture);

          particleSystem.particleTexture = textureParticule.clone();
          particleSystem.emitter = targetMesh;
          particleSystem.color1 = BABYLON.Color4.FromColor3(color1);
          particleSystem.color2 = BABYLON.Color4.FromColor3(color2);
          particleSystem.colorDead = new BABYLON.Color4(0, 0, 0, 0.0);
          particleSystem.minSize = 0.5;
          particleSystem.maxSize = 0.9;
          particleSystem.minLifeTime = 0.2;
          particleSystem.maxLifeTime = 2;
          particleSystem.emitRate = 100;
          particleSystem.createSphereEmitter(1);
          particleSystem.minEmitPower = 0.5;
          particleSystem.maxEmitPower = 1.5;
          particleSystem.updateSpeed = 0.1;
          particleSystem.start();

          setTimeout(() => {
            particleSystem.dispose(false);
          }, 250);
        }
        setParticle(projectile);

        isShoot = true;
        isDragging = false;
        camera.attachControl(canvas, true);

        camera.setTarget(new BABYLON.Vector3(-11, -0.27, -1.63));
        camera.lowerAlphaLimit = null;
        camera.upperAlphaLimit = null;
        camera.lowerBetaLimit = null;
        camera.upperBetaLimit = null;
        camera.alpha = 2.94;
        camera.beta = 1.4;
        camera.radius = 18.5;
      }
    };
  }

  setProjectile();
  setObstacles();

  //   function restartScene() {
  //     if (scene) {
  //       scene.meshes.slice().forEach((mesh) => {
  //         if (mesh.physicsImpostor) {
  //           mesh.physicsImpostor.dispose();
  //         }
  //         mesh.dispose();
  //       });

  //       scene.disablePhysicsEngine();
  //       scene.dispose();
  //     }

  //     scene = createScene();

  //     scene.enablePhysics(new BABYLON.Vector3(0, -9.81, 0), new BABYLON.AmmoJSPlugin());

  //     engine.runRenderLoop(() => {
  //       scene.render();
  //     });
  //   }

  // window.addEventListener("keydown", (event) => {
  //     if (event.key === "r") {
  //         restartScene();
  //     }
  // });

  var advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");

  var label = new BABYLON.GUI.TextBlock();
  label.text = "Ready";
  label.top = "40%";
  label.color = "White";
  label.fontSize = "32px";
  label.outlineWidth = "5";
  label.outlineColor = "Black";
  advancedTexture.addControl(label);

  var againButton = BABYLON.GUI.Button.CreateSimpleButton("AgainButton", "Again?");
  againButton.width = "150px";
  againButton.height = "40px";
  againButton.color = "Black";
  againButton.cornerRadius = 10;
  againButton.background = "Orange";
  againButton.isVisible = false;
  againButton.onPointerUpObservable.add(function () {
    // restartScene();
    window.restartScene();
  });
  advancedTexture.addControl(againButton);

  const creatRing = () => {
    const ring = BABYLON.MeshBuilder.CreateTorus("ring", { diameter: 1.5, thickness: 0.05, tessellation: 32 }, scene);
    ring.position = projectile.absolutePosition;
    ring.material = new BABYLON.StandardMaterial("ringMaterial", scene);
    ring.material.emissiveColor = new BABYLON.Color3(0.11, 0.63, 0.98);
    ring.setEnabled(false);
    return ring;
  };

  const ringEffectMesh = creatRing();
  const animFrame = 30;
  const animationScaling = new BABYLON.Animation(
    "scaling",
    "scaling",
    animFrame,
    BABYLON.Animation.ANIMATIONTYPE_VECTOR3,
    BABYLON.Animation.ANIMATIONLOOPMODE_CYCLE
  );
  const animationPosition = new BABYLON.Animation(
    "position",
    "position.y",
    animFrame,
    BABYLON.Animation.ANIMATIONTYPE_VECTOR3,
    BABYLON.Animation.ANIMATIONLOOPMODE_CYCLE
  );

  const keyScaling = [];
  const keyPositoinY = [];

  keyScaling.push({ frame: 0, value: new BABYLON.Vector3(1, 1, 1) });
  keyScaling.push({ frame: animFrame * 0.5, value: new BABYLON.Vector3(3, 1, 3) });
  keyScaling.push({ frame: animFrame, value: new BABYLON.Vector3(1, 1, 1) });

  keyPositoinY.push({ frame: 0, value: 0 });
  keyPositoinY.push({ frame: animFrame * 0.5, value: 1 });
  keyPositoinY.push({ frame: animFrame, value: 0 });

  animationScaling.setKeys(keyScaling);
  animationPosition.setKeys(keyPositoinY);

  ringEffectMesh.animations.push(animationScaling);
  ringEffectMesh.animations.push(animationPosition);

  scene.beginAnimation(ringEffectMesh, 0, animFrame, true);

  const updateRingEffect = () => {
    const time = performance.now() * 0.001;
    ringEffectMesh.position.y = projectile.absolutePosition.y - Math.sin(time * Math.PI * 2) * 0.75;
  };

  scene.registerBeforeRender(updateRingEffect);

  scene.onBeforeRenderObservable.add(() => {
    if (label) {
      if (isObstaclesReady) {
        label.text = "Set";
      }

      if (projectile.position.x <= -35) {
        label.text = "Go!";
        ringEffectMesh.setEnabled(true);

        isShootable = true;
      } else {
        isShootable = false;
        ringEffectMesh.setEnabled(false);
      }

      if (isShoot) {
        label.dispose();

        setTimeout(() => {
          againButton.isVisible = true;
        }, 2000);
      }
    }
  });
  return scene;
}
